#!/bin/bash
# /trading-check — Full trading monitor (grids, positions, orders, balance, auto-grid log)
SSH="ssh -i ~/.ssh/martin_vm.key -o StrictHostKeyChecking=no -o ConnectTimeout=10 ubuntu@141.253.108.141"
$SSH "echo '=== GRIDS ===' && for g in \$(curl -s http://localhost:8081/api/grid/active 2>/dev/null | python3 -c 'import sys,json; [print(x) for x in json.load(sys.stdin)]'); do S=\$(curl -s http://localhost:8081/api/grid/status/\$g); echo \"\$g RT=\$(echo \$S | python3 -c 'import sys,json; print(json.load(sys.stdin)[\"completedRoundTrips\"])') Fills=\$(echo \$S | python3 -c 'import sys,json; print(len(json.load(sys.stdin)[\"fills\"]))') Profit=\$(echo \$S | python3 -c 'import sys,json; print(json.load(sys.stdin)[\"totalProfit\"])') Mode=\$(echo \$S | python3 -c 'import sys,json; print(json.load(sys.stdin).get(\"gridMode\",\"?\"))')\"; done && echo '=== POSITIONS ===' && curl -s http://localhost:8081/api/bot/positions | python3 -c 'import sys,json; [print(p[\"symbol\"],p[\"side\"],p[\"size\"],\"@\",p[\"price\"]) for p in json.load(sys.stdin)]' && echo '=== ORDERS ===' && curl -s http://localhost:8081/api/bot/orders | python3 -c 'import sys,json; o=json.load(sys.stdin); buys=sum(1 for x in o if x[\"side\"]==\"buy\"); sells=sum(1 for x in o if x[\"side\"]==\"sell\"); print(\"Total:\",len(o),\"(\",buys,\"B /\",sells,\"S)\"); [print(\" \",x[\"symbol\"],x[\"side\"],x.get(\"limitPrice\",x.get(\"stopPrice\",\"?\"))) for x in o]' && echo '=== BALANCE ===' && curl -s http://localhost:8081/api/bot/balance | python3 -c 'import sys,json; f=json.load(sys.stdin)[\"accounts\"][\"flex\"]; print(\"PV:\",round(f[\"portfolioValue\"],2),\"Avail:\",round(f[\"availableMargin\"],2),\"PnL:\",round(f[\"pnl\"],4))' && echo '=== AUTO-GRID ===' && grep -E 'Auto-grid decision|NIGHT|CIRCUIT' ~/martin/app.log | tail -4 && date -u"
